# owner: platform
"""Find the stretches of opening hours that nobody is working."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans


def _check_inside(worked: Iterable[Span], opening: Span) -> None:
    for span in worked:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"{format_span(span)} is outside opening hours")


def _gap_label(begin: int, finish: int) -> List[str]:
    if finish <= begin:
        return []
    text = format_span(Span(begin, finish))
    return [f"gap {text} ({finish - begin} min)"]


# ---
def uncovered_labels(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as 'gap 12:00-13:00 (60 min)'."""
    worked = list(worked)
    _check_inside(worked, opening)
    labels = []
    cursor = opening.start
    for span in merge_spans(worked):
        labels += _gap_label(cursor, span.start)
        cursor = span.end
    return labels + _gap_label(cursor, opening.end)
